// Generated by philote from page /horses/[id]/edit. Do not edit.
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import { horses } from "@/lib/api";

import { submit } from "./actions";
import Form from "./form";

export const metadata: Metadata = { title: "Edit Horse" };

export default function Page({ params }: PageProps<"/horses/[id]/edit">) {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-xl space-y-6">
                <h1 className="font-heading text-4xl">{"Edit Horse"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Loaded params={params} />
                </Suspense>
            </div>
        </main>
    );
}

// Loaded fills the form once its record and choices are in.
async function Loaded({ params }: Pick<PageProps<"/horses/[id]/edit">, "params">) {
    await connection();
    const { id } = await params;
    const result = await horses.get(id);
    if (!result.ok) {
        notFound();
    }
    const record = result.value;
    const options = {};
    const initial = {
        name: record.name,
        breed: record.breed,
        age: String(record.age),
        bio: record.bio,
    };
    return <Form action={submit.bind(null, id)} initial={initial} options={options} />;
}
